// ── chunker.js — client-side text chunking, port of server.py chunk_text() ──
//
// MUST stay behavior-identical to the server's chunker:
//   _SENTENCE_RE, _markdown_sections(), _sentence_slices(), _sentence_chunks(),
//   chunk_text()
// Library "last chunk" resume markers are chunk-index based — a divergence
// would shift every saved position. chunker.test.mjs asserts parity against
// fixtures generated by the Python implementation.
//
// Parity rules (mirroring the Python code exactly):
//  - A `.` only ends a sentence when followed by whitespace/EOL — otherwise
//    it's a token (e.g. "Apache2.0", "$5.00"). `?`/`!`/`…`/newline always end.
//  - Markdown-ish text (≥2 ATX headers, ignoring fenced-code lines) is split
//    at section boundaries first, then sentences are grouped per section.
//  - Sentences longer than `hard` are force-split at the last comma/space.

const _SENTENCE_RE = /(?:[^.!?\n…]|\.(?!\s|$))+(?:[!?\n…]+|\.(?=\s|$))?/g;
const _HEADER_RE = /^#{1,6}[ \t]+\S/;
const _FENCE_RE = /^[ \t]*(?:```|~~~)/;

/**
 * Split markdown-ish text at header lines. Returns [] when fewer than 2
 * headers (fenced-code aware). Preamble becomes its own slice — mirrors
 * server.py _markdown_sections().
 */
function markdownSections(text) {
    const starts = [];
    const lines = text.split('\n');
    // split('\n') drops nothing (it splits all of text), but we need line
    // start offsets to slice the ORIGINAL text (preserving \n of last line).
    const lineStarts = [0];
    for (let i = 0; i < lines.length - 1; i++) {
        lineStarts.push(lineStarts[i] + lines[i].length + 1);
    }

    let fenced = false;
    for (let li = 0; li < lines.length; li++) {
        const line = lines[li];
        if (_FENCE_RE.test(line)) { fenced = !fenced; continue; }
        if (!fenced && _HEADER_RE.test(line)) starts.push(lineStarts[li]);
    }
    if (starts.length < 2) return [];

    const bounds = starts.concat([text.length]);
    const sections = [];
    const pre = text.slice(0, starts[0]);
    if (pre.trim()) sections.push(pre);
    for (let i = 0; i < starts.length; i++) {
        const sec = text.slice(starts[i], bounds[i + 1]);
        if (sec.trim()) sections.push(sec);
    }
    return sections;
}

/**
 * Split text into contiguous sentence slices; concatenating the slices
 * reproduces `text` exactly. Mirrors server.py _sentence_slices().
 */
function sentenceSlices(text) {
    const out = [];
    let pos = 0;
    _SENTENCE_RE.lastIndex = 0;
    let m;
    while ((m = _SENTENCE_RE.exec(text)) !== null) {
        const gap = text.slice(pos, m.index);
        let piece = m[0];
        if (gap) {
            if (out.length) out[out.length - 1] += gap;
            else piece = gap + piece;
        }
        out.push(piece);
        pos = m.index + piece.length;
    }
    if (pos < text.length) {
        const tail = text.slice(pos);
        if (out.length) out[out.length - 1] += tail;
        else out.push(tail);
    }
    return out;
}

/** Group sentences into ~target-char chunks. Mirrors _sentence_chunks(). */
function sentenceChunks(sentences, target, hard) {
    const chunks = [];
    let buf = "";
    for (let s of sentences) {
        if (s.length > hard) {
            if (buf) { chunks.push(buf); buf = ""; }
            while (s.length > hard) {
                const from = 0, to = hard;
                const hard3 = to; // mirrors Python `hard` in rfind bounds
                let cut = s.lastIndexOf(",", to);
                const cutSpace = s.lastIndexOf(" ", to);
                if (cutSpace > cut) cut = cutSpace;
                if (cut === -1) cut = hard; // Python rfind returns max(c1,c2,hard)
                if (cut >= hard) cut = hard;
                // Python: s[:cut+1] if cut < hard else s[:hard]
                if (cut < hard) {
                    chunks.push(s.slice(0, cut + 1));
                    s = s.slice(cut + 1);
                } else {
                    chunks.push(s.slice(0, hard));
                    s = s.slice(hard);
                }
            }
            if (s.trim()) buf = s;
            continue;
        }
        if (buf && buf.length + s.length > target) {
            chunks.push(buf);
            buf = s;
        } else {
            buf += s;
        }
    }
    if (buf.trim()) chunks.push(buf);
    return chunks;
}

/**
 * Split text into sentence-ish chunks of ~target chars.
 * Markdown text splits at sections first; the rest falls through to plain
 * sentence grouping. Parity-checked against server.py chunk_text().
 */
export function chunkText(text, target = 200, hard = 1000) {
    const sections = markdownSections(text);
    if (!sections.length) return sentenceChunks(sentenceSlices(text), target, hard);
    const chunks = [];
    for (const sec of sections) chunks.push(...sentenceChunks(sentenceSlices(sec), target, hard));
    return chunks;
}